//! The web client's icons for Rune: every export of `components/icons` (Hugeicons stroke rounded at
//! the app's 1.5 stroke, drawn in the element's colour) and the Material Icon Theme file-type
//! badges the file explorer, tabs and git rows show (drawn in their own colours). Both catalogs
//! are generated by `scripts/rune/gen-icons.ts`.
//!
//! ```ignore
//! row().child(icon(theme::icons::named("GitBranch").unwrap(), 16.0)).child(icon(theme::icons::file("main.rs", true), 14.0))
//! ```

use rune::Icon;

mod app {
    use rune::Icon;
    include!("../assets/icons/app.rs");
}

mod file_types {
    use rune::Icon;
    include!("../assets/icons/file_types.rs");
}

pub use app::*;

/// The icon `components/icons` exports as `name` (`"GitBranch"`, `"ChevronDownIcon"`), or None.
pub fn named(name: &str) -> Option<&'static Icon> {
    app::BY_NAME
        .binary_search_by(|(n, _)| n.cmp(&name))
        .ok()
        .map(|i| app::BY_NAME[i].1)
}

/// Every export name of `components/icons`, sorted.
pub fn names() -> impl Iterator<Item = &'static str> {
    app::BY_NAME.iter().map(|(n, _)| *n)
}

fn find(table: &[(&str, u16)], key: &str) -> Option<u16> {
    table
        .binary_search_by(|(k, _)| (*k).cmp(key))
        .ok()
        .map(|i| table[i].1)
}

/// The tables for one appearance (light themes use the manifest's light overrides).
struct Manifest {
    file_names: &'static [(&'static str, u16)],
    file_extensions: &'static [(&'static str, u16)],
    folder_names: &'static [(&'static str, u16)],
    folder_names_expanded: &'static [(&'static str, u16)],
    root_folder_names: &'static [(&'static str, u16)],
    root_folder_names_expanded: &'static [(&'static str, u16)],
}

fn manifest(dark: bool) -> Manifest {
    use file_types::*;
    if dark {
        Manifest {
            file_names: DARK_FILE_NAMES,
            file_extensions: DARK_FILE_EXTENSIONS,
            folder_names: DARK_FOLDER_NAMES,
            folder_names_expanded: DARK_FOLDER_NAMES_EXPANDED,
            root_folder_names: DARK_ROOT_FOLDER_NAMES,
            root_folder_names_expanded: DARK_ROOT_FOLDER_NAMES_EXPANDED,
        }
    } else {
        Manifest {
            file_names: LIGHT_FILE_NAMES,
            file_extensions: LIGHT_FILE_EXTENSIONS,
            folder_names: LIGHT_FOLDER_NAMES,
            folder_names_expanded: LIGHT_FOLDER_NAMES_EXPANDED,
            root_folder_names: LIGHT_ROOT_FOLDER_NAMES,
            root_folder_names_expanded: LIGHT_ROOT_FOLDER_NAMES_EXPANDED,
        }
    }
}

fn icon(i: u16) -> &'static Icon {
    file_types::ALL[usize::from(i)]
}

/// The badge for a file named `name`: its whole name (`package.json`), then its dotted suffixes
/// longest first (`d.ts` before `ts`), else the plain file. `resolveFileIconKey` in
/// `material-icon-resolver.ts`.
pub fn file(name: &str, dark: bool) -> &'static Icon {
    let m = manifest(dark);
    let name = name.to_lowercase();
    find(m.file_names, &name)
        .or_else(|| {
            name.match_indices('.')
                .find_map(|(i, _)| find(m.file_extensions, &name[i + 1..]))
        })
        .map_or(icon(file_types::FILE), icon)
}

/// The icon for a folder named `name`, open or closed; `root` for a direct child of the workspace
/// root. `resolveFolderIconKey` in `material-icon-resolver.ts`.
pub fn folder(name: &str, expanded: bool, root: bool, dark: bool) -> &'static Icon {
    let m = manifest(dark);
    let name = name.to_lowercase();
    let named = |closed: &[(&str, u16)], open: &[(&str, u16)]| {
        if expanded {
            find(open, &name).or_else(|| find(closed, &name))
        } else {
            find(closed, &name)
        }
    };
    let root_named = if root {
        named(m.root_folder_names, m.root_folder_names_expanded)
    } else {
        None
    };
    let default = match (root, expanded) {
        (true, true) => file_types::ROOT_FOLDER_EXPANDED,
        (true, false) => file_types::ROOT_FOLDER,
        (false, true) => file_types::FOLDER_EXPANDED,
        (false, false) => file_types::FOLDER,
    };
    icon(
        root_named
            .or_else(|| named(m.folder_names, m.folder_names_expanded))
            .unwrap_or(default),
    )
}

/// Every file-type badge and folder icon, for a gallery.
pub fn file_icons() -> &'static [&'static Icon] {
    file_types::ALL
}
